function setupFlags(){
    defaultFlags.peacock.flags.apDisableComplications = {
        category: "Archipelago",
        title: "disableComplications",
        desc: "When set to true, all Archipelago Missions with complications will have their complications removed.",
        default: false,
    }
    setFlag("apDisableComplications", false)
    defaultFlags.peacock.flags.apEnableDifficultySelection = {
        category: "Archipelago",
        title: "enableDifficultySelection",
        desc: "When set to true, all Archipelago Missions regain their difficulty selection ingame, instead of forcing the YAML selected difficulty.",
        default: false,
    }
    setFlag("apEnableDifficultySelection", false)

    for (const levelName in contractMap){
        setFlag("Level - "+levelName, false)
    }
}
module.exports = function archipelagoCampaign(controller: Controller) {
    logArchipelago("Loading Archipelago Plugin (v0.8.1)")

    setupFlags()
    saveImagesToDisk()
    setupMainMenuTiles()
    setupUnlockables(controller)

    // =============== SETUP CLIENT ENDPOINTS ============
    webFeaturesRouter.use(function(req, res, next){
        var data = "";
        req.on('data', function(chunk){ data += chunk})
        req.on('end', function(){
            // @ts-ignore
            req.rawBody = data;
            try {
                if(data !== undefined && data !== "")
                    req.body = JSON.parse(data)
            } catch (error) {
                errArchipelago("json-body error: "+error)
            }

            next();
        })
    })
    webFeaturesRouter.get("/archipelago", (req,res)=>{
        res.contentType("text").send("OK")
    })
    webFeaturesRouter.post("/archipelago/sendCheckedLocations", (req,res)=>{
        const locationIds: number[] = JSON.parse(String(req.query.items))
        const worked = handleCheckedLocations(controller, locationIds)

        if(worked) {
            res.status(200).send()
        }else{
            res.status(500).contentType("text").send("Error while receiving locations, see console for details")
        }
    })
	webFeaturesRouter.post("/archipelago/sendItems", (req,res)=>{
        const itemIds: number[] = JSON.parse(String(req.query.items))
        const worked = handleRecivedItems(controller, itemIds)

        if(worked) {
            res.status(200).send()
        }else{
            res.status(500).contentType("text").send("Error while receiving item, see console for details")
        }
    })
    webFeaturesRouter.post("/archipelago/setData", (req,res)=>{
        // @ts-ignore
        logArchipelago("Connected to AP with data: "+req.rawBody)
        // logArchipelago(req.body)

        collectedContractPieces = 0
        controller.configManager.configs.allunlockables.splice(0, controller.configManager.configs.allunlockables.length)
		controller.configManager.configs.H2allunlockables.splice(0, controller.configManager.configs.H2allunlockables.length)
        controller.configManager.configs.Legacyallunlockables.splice(0, controller.configManager.configs.Legacyallunlockables.length)

		for(const challangeId in challangeIdToApIdMap){
			controller.challengeService.removeChallenge(challangeId,"h3")
            controller.challengeService.removeChallenge(challangeId,"h2")
            controller.challengeService.removeChallenge(challangeId,"h1")
		}
		challangeIdToApIdMap = {}
		challangesNeedToBeUnset = true;

        for(const id in everythingUnlockables){
            apItemMap[everythingUnlockables[id].apId].h3unlockable = JSON.parse(JSON.stringify(everythingUnlockables[id].unlockableTemplate))
            //H1 and H2 don't have evergreen challange images, just replace it with AP icon
            const nonH3Unlockable = JSON.parse(JSON.stringify(everythingUnlockables[id].unlockableTemplate))
            nonH3Unlockable.Properties.Icon = "images/contracts/ap/campaign.jpg"
            apItemMap[everythingUnlockables[id].apId].h2unlockable = JSON.parse(JSON.stringify(nonH3Unlockable))
            apItemMap[everythingUnlockables[id].apId].h1unlockable = JSON.parse(JSON.stringify(nonH3Unlockable))
    		if(req.body.everythingItemInInventory){
                controller.configManager.configs.allunlockables.push(apItemMap[everythingUnlockables[id].apId].h3unlockable)
                controller.configManager.configs.H2allunlockables.push(apItemMap[everythingUnlockables[id].apId].h2unlockable)
                controller.configManager.configs.Legacyallunlockables.push(apItemMap[everythingUnlockables[id].apId].h1unlockable)
			}
		}

        clearInventoryCache()
        for (const levelName in contractMap){
            setFlag("Level - "+levelName, false)
        }
        modifiedContractMap = {}

        addModifiedMissions(controller, req.body)
		if(req.body.checks.itemPickupChecks.length !== 0 || req.body.checks.splitItemPickupChecks.length !== 0){
			addItemsanityChallanges(controller, req.body)
		}
		if(req.body.checks.disguiseChecks.length !== 0){
			addDisguisesanityChallanges(controller, req.body)
		}
		if(req.body.checks.completionChecks.length !== 0){
			addCompletionChallanges(controller, req.body)
		}
        if(req.body.checks.eliminationChecks.length !== 0){
			addEliminationChallanges(controller, req.body)
		}
		res.status(200).send()
    })
    webFeaturesRouter.get("/archipelago/checks", (req,res) =>{
        res.status(200).contentType("json").send(listOfUnsentChecks)

        while(listOfUnsentChecks.length !== 0){
            listOfUnsentChecks.pop()
        }
    })
    webFeaturesRouter.get("/archipelago/setGoal/:goalMode/:goalDetails{/:moreGoalDetails}{/:evenMoreGoalDetails}",(req,res)=>{
        switch(req.params.goalMode){
            case "contract_collection":
                contractGoalAmount = req.params.goalDetails
                goalLevelString = ""

                editMenuGoalUi(
                    "Contract Collection "+collectedContractPieces+"/"+contractGoalAmount,
                    "$res images/challenges/wet/rat_killthepast.jpg"
                )
                res.status(200).send()
                break;
            case "contract_collection_level_completion":
                contractGoalAmount = req.params.goalDetails
	    	    goalLevelString = req.params.moreGoalDetails+" ("+req.params.evenMoreGoalDetails!.replaceAll("_"," ")+")"

                editMenuGoalUi(
                    "Contract Collection "+collectedContractPieces+"/"+contractGoalAmount+" - "+goalLevelString,
                    "$res "+controller.resolveContract(getContractFromName(req.params.moreGoalDetails!), "h3")!.Metadata.TileImage
                )
	    	    res.status(200).send()
                break;
            case "level_completion":
                editMenuGoalUi(
                    "Goal Level: "+req.params.goalDetails+" ("+req.params.moreGoalDetails!.replaceAll("_"," ")+")",
                    "$res "+controller.resolveContract(getContractFromName(req.params.goalDetails), "h3")!.Metadata.TileImage
                )
                res.status(200).send()
                break;
            case "number_of_completions":
                contractGoalAmount = req.params.goalDetails
	    	    goalLevelString = "Goal Rating: "+req.params.moreGoalDetails

                editMenuGoalUi(
                    "Contract Collection "+collectedContractPieces+"/"+contractGoalAmount+" - "+goalLevelString,
                    "$res images/challenges/wet/rat_killthepast.jpg"
                )
                res.status(200).send()
                break;
            default:
                errArchipelago("Archipelago Client tried to set unknown goal Mode: "+req.params.goalMode)
                res.status(200).send("Invalid goal mode")
        }
    })

    // =============== CAMPAIGN SETUP ==================
    controller.hooks.contributeCampaigns.tap("addArchipelagoCampaign",
        (
            campaigns: Campaign[],
            genSingleMissionFunc: GenSingleMissionFunc,
            genSingleVideoFunc: GenSingleVideoFunc,
            gameVersion: GameVersion,
        ) => {
            const myStoryData = []

            for (const contractId in modifiedContractMap) {
                if (getFlag("Level - "+modifiedContractMap[contractId].name)){
					myStoryData.push(
                        genSingleMissionFunc(contractId, gameVersion)
                    )
                }
            }

            const campaignTemplate = {
                BackgroundImage: "images/contracts/ap/campaign.jpg",
                Image: "",
                Name: "Archipelago",
                Type: "campaign",
                Properties: {
                    BackgroundImage: "images/contracts/ap/campaign.jpg",
                },
                StoryData: myStoryData, // Only add unlocked missions
            }

            campaigns.unshift(campaignTemplate)
        }
    )
    controller.hooks.getNextCampaignMission.tap("setNextCampaignToLatestUnlocked",
        (
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            _contractId: string,
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            _gameVersion: GameVersion,
        ): PlayNextGetCampaignsHookReturn | undefined => {
            return {
                nextContractId: latestUnlockedLevel,
                campaignDetails: {
                    CampaignName: "Archipelago",
                    ParentCampaignName: undefined,
                },
                overrideIndex:0
            }
        }
    )
	controller.challengeService.hooks.onChallengeCompleted.tap("awardCheckOnChallangeCompletion",
		(userId: string,
		challenge: RegistryChallenge,
		gameVersion: GameVersion) => {
			if(challangeIdToApIdMap[challenge.Id] !== undefined){
				checkLocation(challangeIdToApIdMap[challenge.Id])
			}
		}
	)
	controller.hooks.onUserLogin.tap("markChallangesAsChecked",
		(gameVersion: GameVersion,
		userId: string) =>  {
			logArchipelago("User logged in with gameVerison: "+gameVersion)
	        if(challangesNeedToBeUnset){
	        	logArchipelago("Unsetting challanges")
	        	const userData = getUserData(userId, gameVersion)
	        	for(const challangeId in challangeIdToApIdMap){
	        		if(userData.Extensions.ChallengeProgression[challangeId] !== undefined){
	        			userData.Extensions.ChallengeProgression[challangeId] = {
	        				CurrentState: "Start",
	        				State: {},
	        				Completed: false,
	        				Ticked: false,
	        			}
	        		}
	        	}
	        	writeUserData(userId,gameVersion)
                asyncGuard.forceFlush().then(()=>{loadUserData(userId,gameVersion)})
	        	challangesNeedToBeUnset = false;
	        }
	        if(listOfUncheckedChallanges.length !== 0){
	        	const userData = getUserData(userId,gameVersion)
	        	for(const id in listOfUncheckedChallanges){
	        		userData.Extensions.ChallengeProgression[listOfUncheckedChallanges[id]] = {
                    	CurrentState: "Start",
                    	State: {},
                    	Completed: true,
                    	Ticked: true,
                	}
	        	}
	        	while(listOfUncheckedChallanges.length !== 0){
	        		listOfUncheckedChallanges.pop()
	        	}
                writeUserData(userId,gameVersion)
                asyncGuard.forceFlush().then(()=>{loadUserData(userId,gameVersion)})
	        }
		}
	)
    controller.hooks.getContractManifest.tap("getArchipelagoContract",(contractId, gameVersion) => {
        if (modifiedContractMap[contractId] === undefined){
            return undefined
        }

        const manifest:MissionManifest = JSON.parse(JSON.stringify(contractMap[modifiedContractMap[contractId].name].contractData))

        // Make level unplayable if it was reached outside of campaign menu
        if(!getFlag("Level - "+modifiedContractMap[contractId].name)){
            errArchipelago("Attempted to launch contract "+contractId+", but Level - "+modifiedContractMap[contractId].name+" is not unlocked. Making contract unlaunchable...")
            manifest.Metadata.ScenePath = manifest.Metadata.ScenePath+"Refusing to load"
        }

        // Remove GameChangers if override is active
        if(getFlag("apDisableComplications")){
            manifest.Data.GameChangers = []
        }

        // Enable difficulty selection if override is active
        if(getFlag("apEnableDifficultySelection")){
            manifest.Data.GameDifficulties = controller.resolveContract(modifiedContractMap[contractId].oldId, gameVersion)?.Data.GameDifficulties
        }

        // Override used GameChangers in other GameVersions (ex. custom name if name string is not in H1)
        const gameChangers = manifest.Data.GameChangers
        if(gameChangers !== undefined){
            for(const id in gameChangers){
                const record = Object.values(gameChangerApIdToRepoIdMap).filter((element:any) => element.repoId === gameChangers[id])
                if(record.length !== 0){
                    if(record[0].versionsToOverride !== undefined && record[0].versionsToOverride.includes(gameVersion)){
                        for(const keyId in Object.keys(record[0].overrides!)){
                            const key = Object.keys(record[0].overrides!)[keyId]
                            configs.GameChangerProperties[gameChangers[id]][key] = record[0].overrides![key]
                        }
                    }
                }
            }
        }
        return manifest
    })
    /*
    controller.hooks.onMissionEnd.tap("why no SA?",(session:ContractSession) => {
        for(const id in modifiedContractMap){
            if(session.contractId == id){
                for(const challangeId in session.challengeContexts){
                    logArchipelago(challangeId+": ")
                    logArchipelago(session.challengeContexts![challangeId])
                }
                logArchipelago(session.completedObjectives)
                logArchipelago(session.failedObjectives)
                logArchipelago(
                JSON.stringify(session.challengeContexts!["00000000-0000-0000-0000-00"+(baseId+contractMap[modifiedContractMap[id].id].completionApIds.sa)]
               ))
            }
        }
    })*/
	/*
	controller.hooks.newEvent.tap("A",(event: ClientToServerEvent<unknown>, details: {
    gameVersion: GameVersion;
    userId: string;
	}, session: ContractSession)=>{
		if(event.Name == "HoldingIllegalWeapon"){
			logArchipelago(event.Value)
		}
	})*/
	printApIcon()
    logArchipelago("Archipelago Plugin Loaded.")
}